// Package interceptor 提供 gRPC 中間件（對應 pkg/middleware）。
// 每個中間件都有 unary 與 stream 兩個版本，兩者都要掛：只掛 unary 時 streaming RPC 完全不經過它
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package interceptor

import (
	"context"
	"runtime/debug"

	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// Recovery 攔截 unary handler 的 panic，回傳 Internal error 而非 crash
func Recovery(log *logger.Logger) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
		defer recoverPanic(log, info.FullMethod, &err)
		return handler(ctx, req)
	}
}

// StreamRecovery 攔截 stream handler 的 panic。grpc-go 不會 recover handler 的 panic，
// 沒有它時任一 streaming RPC panic 都會讓整個行程崩潰
func StreamRecovery(log *logger.Logger) grpc.StreamServerInterceptor {
	return func(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) (err error) {
		defer recoverPanic(log, info.FullMethod, &err)
		return handler(srv, ss)
	}
}

// recoverPanic 以 defer 呼叫：把 panic 轉成 Internal error 並記錄堆疊
func recoverPanic(log *logger.Logger, method string, err *error) {
	if r := recover(); r != nil {
		if log != nil {
			log.Errorf("gRPC panic recovered in %s: %v\n%s", method, r, debug.Stack())
		}
		*err = status.Errorf(codes.Internal, "internal error")
	}
}
